package vn.edu.eaut.lab7.repository; import vn.edu.eaut.lab7.model.*; import java.util.*; import java.util.stream.*; public class SachRepository { private static final List<Sach> data=new ArrayList<>(List.of(new Sach(1,"S001","Java cơ bản","Nguyễn Văn A","CNTT",120000),new Sach(2,"S002","Lập trình Web","Trần Văn B","CNTT",150000))); private static int next=3; public List<Sach> findAll(){return data;} public Sach findById(int id){return data.stream().filter(x->x.getId()==id).findFirst().orElse(null);} public void add(Sach x){x.setId(next++);data.add(x);} public void update(Sach x){Sach o=findById(x.getId());if(o!=null){o.setMaSach(x.getMaSach());o.setTenSach(x.getTenSach());o.setTacGia(x.getTacGia());o.setTheLoai(x.getTheLoai());o.setGia(x.getGia());}} public void delete(int id){data.removeIf(x->x.getId()==id);} public List<Sach> search(String k){if(k==null||k.isBlank())return data;String q=k.toLowerCase();return data.stream().filter(x->x.getMaSach().toLowerCase().contains(q)||x.getTenSach().toLowerCase().contains(q)).collect(Collectors.toList());} }